slides.solution:
from collections import defaultdict

def group_sum(rows: list[dict], key: str, value: str) -> dict:
    totals = defaultdict(int)
    for row in rows:
        totals[row[key]] += row[value]
    return dict(sorted(totals.items(), key=lambda kv: kv[1], reverse=True))

orders = [
    {"city": "Pune", "product": "Chai", "revenue": 540},
    {"city": "Delhi", "product": "Kettle", "revenue": 1299},
    {"city": "Pune", "product": "Kettle", "revenue": 1299},
]
print(group_sum(orders, "city", "revenue"))

def scale(values: list[float]) -> list[float]:
    if not values:
        return []
    lo, hi = min(values), max(values)
    if hi == lo:
        return [0.0 for _ in values]
    return [round((v - lo) / (hi - lo), 3) for v in values]

print(scale([10, 20, 30, 50]))

slides.tests:
assert scale([10, 20, 30, 50]) == [0.0, 0.25, 0.5, 1.0], "scale([10, 20, 30, 50]) should be [0.0, 0.25, 0.5, 1.0]."
assert scale([3, 1, 2]) == [1.0, 0.0, 0.5], "Keep the original order: scale([3, 1, 2]) is [1.0, 0.0, 0.5]."
assert scale([1, 2, 4]) == [0.0, 0.333, 1.0], "Round each value to 3 decimals: scale([1, 2, 4]) is [0.0, 0.333, 1.0]."
try:
    same = scale([7, 7, 7])
except ZeroDivisionError:
    raise AssertionError("scale([7, 7, 7]) crashed with ZeroDivisionError. When max equals min, return 0.0 for every value.")
assert same == [0.0, 0.0, 0.0], "When every value is the same, return all 0.0. Got " + str(same)
try:
    empty = scale([])
except ValueError:
    raise AssertionError("scale([]) crashed: min() of an empty list fails. Return [] first.")
assert empty == [], "An empty list should give []."
